INSERT INTO phrases (category, text_ja, text_en, text_bn, text_vi, sort_order) VALUES
  ('ActionStep.earthquake', 'まず低く、頭を守り、動かない。丈夫な机の下にもぐり、脚をしっかり持つ。', 'Drop, cover and hold on. Get under a sturdy table and hold its legs.', 'প্রথমে নিচু হন, মাথা রক্ষা করুন, নড়বেন না। মজবুত টেবিলের নিচে ঢুকে পায়া শক্ত করে ধরুন।', 'Cúi thấp, che đầu, giữ chặt. Chui xuống gầm bàn chắc chắn và nắm chặt chân bàn.', 10),
  ('ActionStep.earthquake', '火のそばにいたら、まず離れる。火の始末は揺れが収まってから。', 'If you are near a stove, move away first. Turn off the fire only after the shaking stops.', 'চুলার কাছে থাকলে আগে সরে যান। কাঁপুনি থামার পরেই আগুন বন্ধ করুন।', 'Nếu đang ở gần bếp, hãy tránh xa trước. Chỉ tắt bếp sau khi hết rung lắc.', 20),
  ('ActionStep.earthquake', '揺れが収まったら、ドアや窓を開けて出口を確保する。', 'When the shaking stops, open a door or window to secure an exit.', 'কাঁপুনি থামলে দরজা বা জানালা খুলে বের হওয়ার পথ নিশ্চিত করুন।', 'Khi hết rung, mở cửa ra vào hoặc cửa sổ để đảm bảo lối thoát.', 30),
  ('ActionStep.earthquake', '割れたガラスに注意。必ず靴をはいて移動する。', 'Watch out for broken glass. Always wear shoes when you move.', 'ভাঙা কাচ থেকে সাবধান। চলাফেরার সময় অবশ্যই জুতা পরুন।', 'Cẩn thận mảnh kính vỡ. Luôn mang giày khi di chuyển.', 40),
  ('ActionStep.earthquake', 'ブレーカーを落とし、ガスの元栓を閉めてから家を出る。', 'Switch off the main breaker and close the gas valve before leaving home.', 'বাড়ি ছাড়ার আগে মেইন ব্রেকার বন্ধ করুন এবং গ্যাসের মূল ভালভ বন্ধ করুন।', 'Ngắt cầu dao điện tổng và khóa van gas trước khi rời nhà.', 50),
  ('ActionStep.earthquake', 'エレベーターは使わない。階段で避難する。', 'Do not use elevators. Evacuate by the stairs.', 'লিফট ব্যবহার করবেন না। সিঁড়ি দিয়ে নামুন।', 'Không dùng thang máy. Sơ tán bằng cầu thang bộ.', 60),
  ('ActionStep.earthquake', '近くの避難場所（公園など）へ歩いて行く。車は使わない。', 'Walk to the nearest evacuation site, such as a park. Do not drive.', 'হেঁটে কাছের আশ্রয়স্থলে (যেমন পার্ক) যান। গাড়ি ব্যবহার করবেন না।', 'Đi bộ đến địa điểm sơ tán gần nhất, như công viên. Không đi bằng ô tô.', 70),
  ('ActionStep.earthquake', '家族や学校に安否を連絡する。災害用伝言ダイヤル 171 も使える。', 'Tell your family and school you are safe. You can also use the Disaster Message Dial 171.', 'পরিবার ও স্কুলকে জানান আপনি নিরাপদ। দুর্যোগ বার্তা ডায়াল 171-ও ব্যবহার করতে পারেন।', 'Báo tin an toàn cho gia đình và trường học. Có thể dùng Đường dây tin nhắn thảm họa 171.', 80),
  ('ActionStep.earthquake', '余震に注意。壊れかけた建物・ブロック塀・崖に近づかない。', 'Expect aftershocks. Stay away from damaged buildings, block walls and slopes.', 'আফটারশকের জন্য সতর্ক থাকুন। ক্ষতিগ্রস্ত ভবন, ইটের দেয়াল ও ঢাল থেকে দূরে থাকুন।', 'Cảnh giác dư chấn. Tránh xa nhà bị hư hại, tường gạch và sườn dốc.', 90),
  ('ActionStep.tsunami', '海の近くで強い揺れや長い揺れを感じたら、すぐに高台へ逃げる。', 'If you feel strong or long shaking near the coast, go to high ground immediately.', 'সমুদ্রের কাছে জোরালো বা দীর্ঘ কাঁপুনি অনুভব করলে সঙ্গে সঙ্গে উঁচু জায়গায় যান।', 'Nếu cảm thấy rung mạnh hoặc rung lâu khi ở gần biển, hãy lên chỗ cao ngay lập tức.', 10),
  ('ActionStep.tsunami', '警報を待たない。「遠く」より「高く」へ。', 'Do not wait for the warning. Go high rather than far.', 'সতর্কবার্তার জন্য অপেক্ষা করবেন না। দূরে নয়, উঁচুতে যান।', 'Đừng chờ cảnh báo. Hãy lên cao thay vì chạy xa.', 20),
  ('ActionStep.tsunami', '高台が遠ければ、近くの津波避難ビルの上の階へ。', 'If high ground is too far, go to the upper floors of a tsunami evacuation building.', 'উঁচু জায়গা দূরে হলে কাছের সুনামি আশ্রয় ভবনের উপরের তলায় যান।', 'Nếu chỗ cao ở xa, hãy lên tầng trên của tòa nhà lánh nạn sóng thần gần nhất.', 30),
  ('ActionStep.tsunami', '津波は何度も来る。警報が解除されるまで戻らない。', 'Tsunami waves come again and again. Do not go back until the warning is lifted.', 'সুনামির ঢেউ বারবার আসে। সতর্কতা প্রত্যাহার না হওয়া পর্যন্ত ফিরবেন না।', 'Sóng thần đến nhiều đợt. Không quay lại cho đến khi cảnh báo được dỡ bỏ.', 40),
  ('ActionStep.tsunami', '川沿いを避ける。津波は川をさかのぼる。', 'Stay away from rivers. Tsunamis travel up rivers.', 'নদীর তীর এড়িয়ে চলুন। সুনামি নদী বেয়ে উপরে ওঠে।', 'Tránh xa bờ sông. Sóng thần có thể tràn ngược lên sông.', 50),
  ('ActionStep.flood', '気象情報と市の避難情報をこまめに確認する。', 'Check weather updates and your city''s evacuation information often.', 'আবহাওয়ার খবর ও সিটি অফিসের সরিয়ে নেওয়ার তথ্য নিয়মিত দেখুন।', 'Thường xuyên kiểm tra thông tin thời tiết và thông tin sơ tán của thành phố.', 10),
  ('ActionStep.flood', '「警戒レベル4 避難指示」が出たら全員避難。', 'When "Alert Level 4: Evacuation Instruction" is issued, everyone must evacuate.', '"সতর্কতা স্তর ৪: সরে যাওয়ার নির্দেশ" জারি হলে সবাইকে সরে যেতে হবে।', 'Khi có "Cấp cảnh báo 4: Chỉ thị sơ tán", tất cả mọi người phải sơ tán.', 20),
  ('ActionStep.flood', '暗くなる前、雨が強くなる前に避難する。', 'Evacuate before dark and before the rain gets heavy.', 'অন্ধকার হওয়ার আগে এবং বৃষ্টি বাড়ার আগেই সরে যান।', 'Sơ tán trước khi trời tối và trước khi mưa to.', 30),
  ('ActionStep.flood', '流れのある水の中は歩かない。ひざ下の水でも足を取られる。', 'Do not walk through flowing water. Even knee-deep water can knock you down.', 'স্রোতযুক্ত পানির মধ্যে হাঁটবেন না। হাঁটু সমান পানিও আপনাকে ফেলে দিতে পারে।', 'Không đi qua dòng nước chảy. Nước ngang đầu gối cũng có thể làm bạn ngã.', 40),
  ('ActionStep.flood', '外に出るのが危険なら、建物の2階以上へ（垂直避難）。', 'If going outside is dangerous, move to the second floor or higher (vertical evacuation).', 'বাইরে যাওয়া বিপজ্জনক হলে ভবনের দোতলা বা তার উপরে যান (উল্লম্ব আশ্রয়)।', 'Nếu ra ngoài nguy hiểm, hãy lên tầng 2 trở lên (sơ tán theo chiều dọc).', 50),
  ('ActionStep.flood', '川や用水路の様子を見に行かない。', 'Never go to check on rivers or canals.', 'নদী বা খালের অবস্থা দেখতে যাবেন না।', 'Tuyệt đối không đi xem sông hay kênh mương.', 60),
  ('Safety', '私は無事です。けがはありません。', 'I am safe. I am not injured.', 'আমি নিরাপদ আছি। আমার কোনো আঘাত নেই।', 'Tôi an toàn. Tôi không bị thương.', 10),
  ('Safety', '自宅にいます。今のところ安全です。', 'I am at home. It is safe for now.', 'আমি বাসায় আছি। এই মুহূর্তে নিরাপদ।', 'Tôi đang ở nhà. Hiện tại vẫn an toàn.', 20),
  ('Safety', '今、避難所にいます。', 'I am at an evacuation shelter now.', 'আমি এখন একটি আশ্রয়কেন্দ্রে আছি।', 'Hiện tôi đang ở nơi sơ tán.', 30),
  ('Safety', '軽いけがをしていますが、大丈夫です。', 'I have a minor injury, but I am OK.', 'আমার সামান্য আঘাত লেগেছে, কিন্তু আমি ঠিক আছি।', 'Tôi bị thương nhẹ nhưng vẫn ổn.', 40),
  ('Safety', '助けが必要です。連絡してください。', 'I need help. Please contact me.', 'আমার সাহায্য দরকার। দয়া করে যোগাযোগ করুন।', 'Tôi cần giúp đỡ. Hãy liên lạc với tôi.', 50),
  ('Food', '飲料水：1人1日3リットル', 'Drinking water: 3 L per person per day', 'খাবার পানি: জনপ্রতি দিনে ৩ লিটার', 'Nước uống: 3 lít mỗi người mỗi ngày', 10),
  ('Food', '主食：パックご飯・アルファ米', 'Staple food: ready-to-eat rice packs, instant (alpha) rice', 'প্রধান খাবার: রেডি-টু-ইট ভাতের প্যাকেট, ইনস্ট্যান্ট (আলফা) চাল', 'Lương thực chính: cơm đóng gói, gạo ăn liền (alpha)', 20),
  ('Food', 'カップ麺・乾麺・缶詰パン', 'Cup noodles, dried noodles, canned bread', 'কাপ নুডলস, শুকনো নুডলস, টিনজাত রুটি', 'Mì ly, mì khô, bánh mì đóng hộp', 30),
  ('Food', '缶詰（魚・肉・豆）・レトルトカレー', 'Canned fish, meat and beans, ready-made curry pouches', 'টিনজাত মাছ, মাংস ও ডাল, রেডিমেড কারি', 'Đồ hộp (cá, thịt, đậu), cà ri đóng gói', 40),
  ('Food', '野菜ジュース・果物の缶詰', 'Vegetable juice, canned fruit', 'সবজির জুস, টিনজাত ফল', 'Nước ép rau, trái cây đóng hộp', 50),
  ('Food', 'お菓子・栄養補助食品（チョコ・ようかん）', 'Snacks and energy food (chocolate, yokan)', 'শুকনো খাবার ও শক্তিবর্ধক খাবার (চকলেট, ইয়োকান)', 'Đồ ăn vặt và thực phẩm năng lượng (sô-cô-la, yokan)', 60),
  ('Food', 'カセットコンロとガスボンベ（1人1週間で約6本）', 'Portable gas stove and cartridges (about 6 per person per week)', 'পোর্টেবল গ্যাস চুলা ও গ্যাস ক্যান (জনপ্রতি সপ্তাহে প্রায় ৬টি)', 'Bếp ga mini và bình ga (khoảng 6 bình mỗi người mỗi tuần)', 70),
  ('Food', 'ハラール・ベジタリアンなど自分が食べられる食品は多めに。避難所にあるとは限らない', 'Keep extra food you can eat (halal, vegetarian, allergy-safe). Shelters may not have it', 'নিজে খেতে পারেন এমন খাবার (হালাল, নিরামিষ) বেশি রাখুন। আশ্রয়কেন্দ্রে নাও থাকতে পারে', 'Dự trữ thêm thực phẩm bạn ăn được (halal, chay). Nơi sơ tán có thể không có', 80),
  ('Food', 'ローリングストック：普段から食べて、食べた分を買い足す', 'Rolling stock: eat it in daily life and buy more as you use it', 'রোলিং স্টক: নিয়মিত খান, যতটুকু খাবেন ততটুকু আবার কিনুন', 'Dự trữ luân phiên: ăn hằng ngày, dùng bao nhiêu mua bù bấy nhiêu', 90),
  ('General', '非常持ち出し袋（リュック）を玄関の近くに置く', 'Keep an emergency backpack near the front door', 'জরুরি ব্যাগ (ব্যাকপ্যাক) দরজার কাছে রাখুন', 'Để ba lô khẩn cấp gần cửa ra vào', 10),
  ('General', '在留カード・パスポート・保険証のコピー', 'Copies of your residence card, passport and health insurance card', 'রেসিডেন্স কার্ড, পাসপোর্ট ও স্বাস্থ্য বীমা কার্ডের কপি', 'Bản sao thẻ cư trú, hộ chiếu và thẻ bảo hiểm y tế', 20),
  ('General', '現金（小銭も）。停電するとカードが使えない', 'Cash, including coins. Cards may not work in a blackout', 'নগদ টাকা (খুচরা সহ)। বিদ্যুৎ না থাকলে কার্ড চলবে না', 'Tiền mặt (cả tiền xu). Mất điện thì không dùng được thẻ', 30),
  ('General', 'モバイルバッテリー・充電ケーブル', 'Power bank and charging cable', 'পাওয়ার ব্যাংক ও চার্জিং কেবল', 'Sạc dự phòng và cáp sạc', 40),
  ('General', '懐中電灯・ヘッドライト・予備の電池', 'Flashlight or headlamp and spare batteries', 'টর্চলাইট বা হেডল্যাম্প ও অতিরিক্ত ব্যাটারি', 'Đèn pin hoặc đèn đội đầu và pin dự phòng', 50),
  ('General', '携帯ラジオ', 'Portable radio', 'পোর্টেবল রেডিও', 'Radio cầm tay', 60),
  ('General', '携帯トイレ（1人1日5回分）', 'Portable toilet bags (5 per person per day)', 'পোর্টেবল টয়লেট ব্যাগ (জনপ্রতি দিনে ৫টি)', 'Túi vệ sinh khẩn cấp (5 túi mỗi người mỗi ngày)', 70),
  ('General', '軍手・スリッパ・雨具・防寒シート', 'Work gloves, slippers, rain gear, emergency blanket', 'কাজের দস্তানা, স্লিপার, বৃষ্টির পোশাক, জরুরি কম্বল', 'Găng tay, dép, áo mưa, chăn giữ nhiệt', 80),
  ('General', '家具を壁に固定し、寝る場所の近くに倒れる物を置かない', 'Fix furniture to the wall. Keep heavy things away from where you sleep', 'আসবাবপত্র দেয়ালে আটকে রাখুন। ঘুমানোর জায়গার কাছে ভারী জিনিস রাখবেন না', 'Cố định đồ đạc vào tường. Không để đồ nặng gần chỗ ngủ', 90),
  ('General', '家族・友達と集合場所と連絡方法を決めておく', 'Agree on a meeting point and a way to contact family and friends', 'পরিবার ও বন্ধুদের সাথে মিলিত হওয়ার স্থান ও যোগাযোগের উপায় ঠিক করে রাখুন', 'Thống nhất điểm hẹn và cách liên lạc với gia đình, bạn bè', 100),
  ('General', '大使館と学校の緊急連絡先を紙にも書いておく', 'Write your embassy and school emergency numbers on paper too', 'দূতাবাস ও স্কুলের জরুরি নম্বর কাগজেও লিখে রাখুন', 'Ghi số khẩn cấp của đại sứ quán và trường lên giấy', 110),
  ('Medical', '常備薬・お薬手帳（コピー）', 'Your regular medicines and medication notebook (copy)', 'নিয়মিত ওষুধ ও ওষুধের নোটবুক (কপি)', 'Thuốc thường dùng và sổ tay thuốc (bản sao)', 10),
  ('Medical', '絆創膏・ガーゼ・包帯・消毒液', 'Plasters, gauze, bandages, disinfectant', 'ব্যান্ডেজ, গজ, পট্টি, জীবাণুনাশক', 'Băng cá nhân, gạc, băng cuộn, thuốc sát trùng', 20),
  ('Medical', 'マスク・ウェットティッシュ・手指消毒液', 'Masks, wet wipes, hand sanitizer', 'মাস্ক, ভেজা টিস্যু, হ্যান্ড স্যানিটাইজার', 'Khẩu trang, khăn ướt, nước rửa tay khô', 30),
  ('Medical', '生理用品・歯ブラシ・眼鏡やコンタクトの予備', 'Sanitary products, toothbrush, spare glasses or contact lenses', 'স্যানিটারি পণ্য, টুথব্রাশ, অতিরিক্ত চশমা বা কন্টাক্ট লেন্স', 'Đồ vệ sinh phụ nữ, bàn chải đánh răng, kính hoặc kính áp tròng dự phòng', 40),
  ('Medical', '迷ったら #7119（救急安心センター）に相談。命の危険があれば 119', 'Not sure? Call #7119 for medical advice. If life is in danger, call 119', 'নিশ্চিত না হলে চিকিৎসা পরামর্শের জন্য #7119-এ কল করুন। জীবনের ঝুঁকি থাকলে 119', 'Nếu phân vân, gọi #7119 để được tư vấn y tế. Nguy hiểm tính mạng thì gọi 119', 50);
